import { spawnSync } from 'node:child_process';
import { globSync, readFileSync, writeFileSync } from 'node:fs';

const generatedHeader =
  "// Generated by `blume translate` — edit the default locale's meta file\n// and rerun the translation instead of editing this copy.\n";

const args = process.argv.slice(2);
if (!args.includes('--normalize-only')) {
  const run = spawnSync('blume', ['translate', '--codex', ...args], { stdio: 'inherit' });
  if (run.error) {
    throw run.error;
  }
  process.exitCode = run.status ?? 1;
}

if (!args.includes('--check')) {
  const metaFiles = globSync('content/docs/**/meta.ts');
  for (const file of metaFiles) {
    const source = readFileSync(file, 'utf8');
    if (source.startsWith(generatedHeader)) {
      writeFileSync(file, source.slice(generatedHeader.length));
    }
  }
}
